import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compresses all files in the source folder using gzip and moves them 
    to the destination folder as a background process.
    """
    result = {
        'success': True,
        'message': '',
        'failed_files': []
    }

    # Ensure source exists
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist.', 'failed_files': []}

    # Ensure destination exists
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]

    if not files:
        return {'success': True, 'message': 'No files found to compress.', 'failed_files': []}

    for filename in files:
        src_path = os.path.join(src_folder, filename)
        dst_path = os.path.join(dst_folder, filename + ".gz")

        try:
            # We use gzip -c to stream to stdout and redirect to the destination file.
            # This keeps the original file intact in the source (per standard gzip behavior)
            # or we can move it after. Here we perform the compression directly to the dest.
            with open(dst_path, 'wb') as f_out:
                process = subprocess.Popen(
                    ['gzip', '-c', src_path],
                    stdout=f_out,
                    stderr=subprocess.PIPE
                )
                process.wait()

            if process.returncode != 0:
                result['failed_files'].append(filename)
                if os.path.exists(dst_path):
                    os.remove(dst_path)
            else:
                # Optionally remove the original file if strictly "moving" is required
                os.remove(src_path)

        except Exception:
            result['failed_files'].append(filename)

    if result['failed_files']:
        result['success'] = False
        result['message'] = f"Operation completed with {len(result['failed_files'])} failures."
    else:
        result['message'] = "All files compressed and moved successfully."

    return result

